1: import { Injectable } from '@angular/core';
2: import { HttpClient, HttpHeaders } from '@angular/common/http';
3: import { catchError, map } from 'rxjs/operators';
4: import { HttpErrorManager } from './errorManager';
5: import { environment } from '../../environments/environment';
6: 
7: /**
8:  * This class manage the http connections with internal REST services. Use the response format {
9:  *  Code: 'xxxxx',
10:  *  Body: 'Some Data' (this element is returned if the request is success)
11:  *  ...
12:  * }
13:  */
14: @Injectable({
15:     providedIn: 'root',
16: })
17: 
18: 
19: export class RequestManager {
20:     private path!: string;
21:     public httpOptions: any;
22:     constructor(
23:         private http: HttpClient,
24:         private errManager: HttpErrorManager
25:     ) {
26:         const acces_token = window.localStorage.getItem('access_token');
27:         if (acces_token !== null) {
28:             this.httpOptions = {
29:                  headers: new HttpHeaders({
30:                    'Authorization': `Bearer ${acces_token}`,
31:                    'Accept': 'application/json',
32:                  }),
33:             }
34:         }
35:     }
36: 
37: 
38:     /**
39:      * Use for set the source path of the service (service's name must be present at src/environment/environment.ts)
40:      * @param service: string
41:      */
42:     public setPath(service: string) {
43:         this.path = (environment as any)[service];
44:       }
45: 
46:     /**
47:      * Perform a GET http request
48:      * @param endpoint service's end-point
49:      * @param params (an Key, Value object with que query params for the request)
50:      * @returns Observable<any>
51:      */
52:     get(endpoint: any) {
53:         return this.http.get<any>(`${this.path}${endpoint}`, this.httpOptions).pipe(
54:             map(
55:                 (res) => {
56:                     const responseBody = res as { Body?: any };
57:                     return responseBody?.Body ?? res;
58:                 },
59:             ),
60:             catchError(this.errManager.handleError.bind(this)),
61:         );
62: 
63:     }
64: 
65:     /**
66:      * Perform a POST http request
67:      * @param endpoint service's end-point
68:      * @param element data to send as JSON
69:      * @returns Observable<any>
70:      */
71:     post(endpoint: any, element: any){
72:       const postOptions = {
73:         ...this.httpOptions,
74:         headers: this.httpOptions.headers.set('Content-Type', 'application/json')
75:       }
76:       return this.http.post<any>(`${this.path}${endpoint}`, element, postOptions).pipe(
77:         catchError(this.errManager.handleError),
78:       );
79:     }
80: 
81:     postFIle(endpoint: any, element: any) {
82:          
83:         const acces_token = window.localStorage.getItem('access_token');
84:         if (acces_token != '') {
85:           const postOptions = {
86:             headers: new HttpHeaders({
87:               Authorization: `Bearer ${acces_token}`,
88:             }),
89:           };
90:           console.log(`${this.path}${endpoint}`,element,postOptions);
91:           return this.http
92:             .post<any>(
93:               `${this.path}${endpoint}`,element,postOptions)
94:             .pipe(catchError(this.errManager.handleError));
95:         }
96:         return this.http
97:           .post<any>(
98:             `${this.path}${endpoint}`,
99:             element
100:           )
101:           .pipe(catchError(this.errManager.handleError));
102:       }
103: 
104:     /**
105:      * Perform a PUT http request
106:      * @param endpoint service's end-point
107:      * @param element data to send as JSON, With the id to UPDATE
108:      * @returns Observable<any>
109:      */
110:     put(endpoint: any, element: { Id: any; }) {
111:       const putOptions = {
112:         ...this.httpOptions,
113:         headers: this.httpOptions.headers.set('Content-Type', 'application/json')
114:       }
115:         const path = (element.Id) ? `${this.path}${endpoint}/${element.Id}` : `${this.path}${endpoint}`;
116:         return this.http.put<any>(path, element, putOptions).pipe(
117:             catchError(this.errManager.handleError),
118:         );
119:     }
120: 
121: 
122:  
123:     /**
124:      * Perform a DELETE http request
125:      * @param endpoint service's end-point
126:      * @param id element's id for remove
127:      * @returns Observable<any>
128:      */
129:     delete(endpoint: any, id: any) {
130:         return this.http.delete<any>(`${this.path}${endpoint}/${id}`, this.httpOptions).pipe(
131:             catchError(this.errManager.handleError),
132:         );
133:     }
134: };
