19: export class ListarContratosComponent {
20:   @ViewChild(MatPaginator, { static: true }) paginator!: MatPaginator;
21:   @ViewChild(MatSort, { static: true }) sort!: MatSort;
22:   documento_supervisor: string;
23:   contratos_supervisor: any;
