65: 
66:             this.loading = false;
67:           } else {
68:             this.dataSource = this.contratos_supervisor.contratos;
69:             this.dataSource = this.contratos_supervisor.contratos.map(
70:               (contrato: any) => {
71:                 return {
72:                   Contrato: contrato,
73:                   numeroContrato: contrato.NumeroContratoSuscrito,
74:                   vigencia: contrato.Vigencia,
75:                   tipoContrato: contrato.TipoContrato,
76:                   rp: contrato.NumeroRp,
77:                   vigenciaRp: contrato.VigenciaRp,
78:                   nombreProveedor: contrato.NombreProveedor,
