85:                     },
86:                   ],
87:                 };
88:               }
89:             );
90:             this.loading = false;
91:           }
92:         },
93:         error: (error: any) => {
94:           this.popUpManager.showErrorAlert(
95:             this.translate.instant(
96:               'Error al intentar cargar los contratos del supervisor.'
97:             )
98:           );
99: 
100: 
101:         }
102:       });
103:   }
104: 
105: 
