116: 
117:   displayedColumns: any[] = [
118:     {def: 'numeroContrato', header: 'NUMERO CONTRATO' },
119:     {def: 'vigencia', header: 'VIGENCIA' },
120:     {def: 'tipoContrato', header: 'TIPO CONTRATO'},
121:     {def: 'rp', header: 'RP' },
122:     {def: 'vigenciaRp', header: 'VIGENCIA RP' },
123:     {def: 'nombreProveedor', header: 'NOMBRE PROVEEDOR' },
124:     {def: 'dependencias', header: 'DEPENDENCIAS'},
125:     {
126:       def: 'acciones',
127:       header: 'ACCIONES',
128:       isAction: true,
129:     }
130:   ];
131: 
