133:     let info = this.user.obtenerInformacionPersona().subscribe({
134:       next: (response) => {
135:         if (response != null) {
136:           this.nombreSupervisor =
137:             response[0].PrimerNombre +
138:             ' ' +
139:             response[0].SegundoNombre +
140:             ' ' +
141:             response[0].PrimerApellido +
142:             ' ' +
143:             response[0].SegundoApellido;
144:         }
145:       },
146:     });
147:   }
148: 
