151:       disableClose: true,
152:       height: 'auto',
153:       width: 'auto',
154:       maxWidth: '60vw',
155:       maxHeight: '80vh',
156:       data:{
157:         CumplidoProveedorId:12,
158:         Config:{
159:           mode:Mode.CD,
160:           rolUsuario:RolUsuario.S
