59:     { def: 'VigenciaContrato', header: 'VIGENCIA', filter: true },
60:     { def: 'TipoContrato', header: 'TIPO CONTRATO', filter: true },
61:     { def: 'Rp', header: 'RP', filter: true },
62:     { def: 'VigenciaRP', header: 'VIGENCIA RP', filter: true },
