7: @Injectable({
8:   providedIn: 'root',
9: })
10: export class AuthGuard implements CanActivate {
11:   user!:DecodedToken;
12:   pathForRol:any={
13:     'pages/cumplido-satisfaccion/:cumplidoId':['SUPERVISOR']
14:   }
15:   constructor(
16:     private popUpManager: PopUpManager,
17:     private userService: UserService
18:   ) {
19:     this.user=userService.getPayload()
20:   }
21: 
22:   canActivate(route: ActivatedRouteSnapshot, state: RouterStateSnapshot) {
23: 
24:     const menuInfo = localStorage.getItem('menu');
25:     const menuPermisos = menuInfo ? JSON.parse(atob(menuInfo)) : null;
26:     const fullUrl = window.location.href;
27:     const url = new URL(fullUrl);
28:     //const path = url.pathname.startsWith('/') ? url.pathname.substring(1) : url.pathname;
29:     const path= 'pages/'+route.routeConfig?.path
30: 
31:     // Obtener parámetros de la ruta
32:     const params = route.params;
33: 
34: 
35: 
36:     if (menuPermisos != null) {
37:       
38:       // Pasar tanto la URL como los parámetros a la función de verificación
39:       if (checkUrlExists(menuPermisos, path?path:'', params)) {
40:         return true;
41:       }else{
42:         if(this.pathForRol[path]!=undefined && this.pathForRol[path].some((item:string) => this.user.role.includes(item))){
43:           return true
44:         }
45:       }
46:     }
47: 
48:     this.popUpManager.showErrorAlert('No tienes permiso para acceder a esta ruta o no has iniciado sesión');
49:     return false;
50:   }
51: 
52:   canActivateChild(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): boolean {
53:     return this.canActivate(route, state);
54:   }
55: }
56: 
57: // Recorrer el menú para verificar si la URL y los parámetros existen
58: function checkUrlExists(menuItems: any, targetUrl: string, params: any) {
59:   return menuItems.some((item: any) => {
60:     if (item.Url === targetUrl && checkParams(item.Params, params)) {
61:       return true;
62:     }
63:     if (item.Opciones && item.Opciones.length > 0) {
64:       return checkUrlExists((item.Opciones), targetUrl, params);
65:     }
66:     return false;
67:   });
68: }
69: 
70: // Verificar los parámetros de la ruta
71: function checkParams(expectedParams: any, actualParams: any): boolean {
72:   if (!expectedParams) {
73:     return true; // No se requieren parámetros específicos
74:   }
75:   for (let key in expectedParams) {
76:     if (expectedParams[key] !== actualParams[key]) {
77:       return false; // Un parámetro no coincide
78:     }
79:   }
80:   return true; // Todos los parámetros coinciden
81: }

